#!/usr/bin/env python3
"""Install the REBUILT generated guest bundles (bundle-refresh/job-bundles-v2.sh output) into the reconciled candidate, by
the same guarded index procedure as refresh.py. No commit, ref, push or build here; work/enclave is not read or written.

  refresh-bundles.py --plan | --apply
Checks before any write:
  - the candidate is exactly tree 7990461e (index == write-tree, directory == index, no extra file);
  - its 4 generated files are the OLD ones (their manifests' recorded sha256), and the new files are the job's outputs;
  - SOURCE-TO-BUNDLE: every non-node_modules input hash in each NEW manifest equals that file in the candidate itself,
    except relay/network-runtime.bundle.mjs (gitignored, generated by relay/build-network.mjs), which must equal the
    job's generated copy; every node_modules input equals the OLD manifest's (dependencies unchanged);
  - each new manifest's own sha256/bytes describe its bundle; the platform-api sidecar source matches the candidate."""
import hashlib, json, os, subprocess, sys, shutil, datetime
from pathlib import Path

HERE = Path(__file__).resolve().parent
UG, CAND, B = HERE / 'upstream.git', HERE.parent / 'reconciled-candidate', HERE.parent / 'bundle-refresh'
OUT = HERE / 'refresh-20261021-bundles'
UHEAD, OLD_TREE = '7752a4239b3bec2cf452491cd1b95164a8c2bdb8', '7990461e081fbed62fd41eb2918666cbb10af8cc'
ENV = {**os.environ, 'GIT_OPTIONAL_LOCKS': '0', 'LC_ALL': 'C'}
sha = lambda b: hashlib.sha256(b).hexdigest()
fsha = lambda p: sha(Path(p).read_bytes())
def git(*a, env=ENV, input=None): return subprocess.run(['git', '--git-dir', str(UG), *a], capture_output=True, check=True, env=env, input=input).stdout
FILES = ['metal/guest/platform-api.bundle.mjs', 'metal/guest/platform-api.bundle.mjs.manifest.json',
         'metal/guest/mcp-server.bundle.mjs', 'metal/guest/mcp-server.bundle.mjs.manifest.json']
NM = lambda k: 'node_modules' in k

def main():
    mode = sys.argv[1] if len(sys.argv) > 1 else '--plan'; assert mode in ('--plan', '--apply')
    rep = {'at': datetime.datetime.now(datetime.timezone.utc).isoformat(), 'mode': mode, 'oldTree': OLD_TREE}
    stop = []
    idx = HERE / 'candidate.index'; ienv = {**ENV, 'GIT_INDEX_FILE': str(idx), 'GIT_WORK_TREE': str(CAND)}
    if git('write-tree', env=ienv).decode().strip() != OLD_TREE: stop.append('candidate.index is not 7990461e')
    subprocess.run(['git', '--git-dir', str(UG), 'update-index', '-q', '--refresh'], env=ienv)
    if git('diff-files', '--name-status', env=ienv) or git('ls-files', '-o', env=ienv): stop.append('candidate directory differs from its index')
    corr = {}
    INV = json.load(open(HERE / 'candidate-inventory.json'))
    for b in ('platform-api', 'mcp-server'):
        old = json.loads((CAND / f'metal/guest/{b}.bundle.mjs.manifest.json').read_text())
        new = json.loads((B / f'out/{b}.bundle.mjs.manifest.json').read_text())
        have = fsha(CAND / f'metal/guest/{b}.bundle.mjs')
        # known case (RECONCILIATION.txt): T rewrote the route literal INSIDE the committed platform-api bundle, so it is
        # T(the old manifest's bundle) - accepted only as exactly that recorded before/after pair
        tpair = next((x for x in INV.get('brandTransformAffectedLocalFiles', []) if x['path'] == f'metal/guest/{b}.bundle.mjs'), None)
        if have != old['sha256'] and not (tpair and tpair['beforeSha256'] == old['sha256'] and tpair['afterSha256'] == have):
            stop.append(f'{b}: the candidate bundle is neither its old manifest\'s nor the recorded T of it')
        nb = (B / f'out/{b}.bundle.mjs').read_bytes()
        if sha(nb) != new['sha256'] or len(nb) != new['bytes']: stop.append(f'{b}: the new manifest does not describe the new bundle')
        src_bad, dep_bad = [], []
        for k, h in new['inputs'].items():
            if NM(k):
                if old['inputs'].get(k) != h: dep_bad.append(k)
            elif k == 'relay/network-runtime.bundle.mjs':
                if fsha(B / 'network-runtime.bundle.mjs') != h: src_bad.append(k)
            elif not (CAND / k).exists() or fsha(CAND / k) != h: src_bad.append(k)
        for side, v in (new.get('sidecars') or {}).items():
            if fsha(CAND / v['source']) != v['sha256']: src_bad.append(f'sidecar {side} <- {v["source"]}')
        if src_bad: stop.append(f'{b}: inputs not equal to the candidate: {src_bad[:5]}')
        if dep_bad: stop.append(f'{b}: dependency inputs changed vs the old manifest: {dep_bad[:5]}')
        corr[b] = {'oldSha256': old['sha256'], 'newSha256': new['sha256'], 'bytes': new['bytes'], 'inputs': len(new['inputs']),
                   'sourceInputs': sum(1 for k in new['inputs'] if not NM(k)), 'dependencyInputs': sum(1 for k in new['inputs'] if NM(k)),
                   'sourceInputsChangedVsOld': sorted(k for k in new['inputs'] if not NM(k) and old['inputs'].get(k) != new['inputs'][k]),
                   'allSourceInputsEqualCandidate': not src_bad, 'dependenciesEqualOldManifest': not dep_bad,
                   'manifestSha256': fsha(B / f'out/{b}.bundle.mjs.manifest.json')}
    corr['network-runtime (generated prerequisite, gitignored, NOT in the candidate)'] = {
        'sha256': fsha(B / 'network-runtime.bundle.mjs'), 'builtBy': 'relay/build-network.mjs (in bundle-refresh/tree)',
        'mainPrebuilt': '3de76b54cf64fc06b5965bcc989290d6653de6e4f6e59f00b0da52e39218d76a', 'differsOnlyBy': 'relay/snp-verify.mjs (candidate == T(main): one comment)'}
    rep['sourceToBundle'] = corr; rep['stop'] = stop
    OUT.mkdir(exist_ok=True)
    if stop or mode == '--plan':
        json.dump(rep, open(OUT / f'bundles-{mode[2:]}.json', 'w'), indent=1); print(json.dumps({'stop': stop, 'sourceToBundle': corr}, indent=1)); sys.exit(1 if stop else 0)
    for f in ('candidate.index', 'candidate-all.sha256', 'candidate-changed-paths.tsv', 'candidate-inventory.json'):
        dst = OUT / (f + '.7990461e'); assert not dst.exists(), f'{dst} exists'; shutil.copy2(HERE / f, dst)
    for f in FILES:
        data = (B / 'out' / Path(f).name).read_bytes(); fp = CAND / f
        mode_ = '100755' if os.stat(fp).st_mode & 0o111 else '100644'
        fp.write_bytes(data); os.chmod(fp, 0o755 if mode_ == '100755' else 0o644)
        oid = git('hash-object', '-w', '--stdin', input=data).decode().strip()
        git('update-index', '--add', '--cacheinfo', f'{mode_},{oid},{f}', env=ienv)
    new_tree = git('write-tree', env=ienv).decode().strip()
    subprocess.run(['git', '--git-dir', str(UG), 'update-index', '-q', '--refresh'], env=ienv)
    assert not git('diff-files', '--name-status', env=ienv) and not git('ls-files', '-o', env=ienv), 'directory != index after apply'
    rd = HERE / 'rederive.index'; rd.unlink(missing_ok=True); renv = {**ENV, 'GIT_INDEX_FILE': str(rd), 'GIT_WORK_TREE': str(CAND)}
    git('read-tree', UHEAD, env=renv); git('add', '-A', '-f', '.', env=renv); rtree = git('write-tree', env=renv).decode().strip(); rd.unlink()
    assert rtree == new_tree, (rtree, new_tree)
    delta = sorted(l.split('\t', 1)[1] for l in git('diff-tree', '-r', '--no-renames', OLD_TREE, new_tree).decode().splitlines())
    assert delta == sorted(FILES), delta
    lst = subprocess.run(f"cd '{CAND}' && find . \\( -type f -o -type l \\) -print0 | sort -z | xargs -0 sha256sum", shell=True, capture_output=True, check=True).stdout
    (HERE / 'candidate-all.sha256').write_bytes(lst)
    inv = json.load(open(HERE / 'candidate-inventory.json')); by = {c['path']: c for c in inv['changedPaths']}
    diff = git('diff-tree', '-r', '-z', '--no-renames', UHEAD, new_tree).split(b'\0'); changed = []; i = 0
    while i < len(diff) - 1:
        om, nm, oo, no, s = diff[i].decode().lstrip(':').split(); path = diff[i + 1].decode(); i += 2
        fp = CAND / path
        changed.append({'path': path, 'status': s, 'oldMode': om, 'newMode': nm, 'oldBlob': oo, 'newBlob': no,
                        'sha256': (sha(os.readlink(fp).encode()) if fp.is_symlink() else fsha(fp)) if s != 'D' else None,
                        'decision': 'generated (rebuilt from this candidate)' if path in FILES else (by.get(path, {}).get('decision') or 'local')})
    inv['changedPaths'] = changed; inv['candidateTree'] = new_tree; inv['changedVsUpstream'] = len(changed)
    inv.setdefault('refreshes', []).append({'at': rep['at'], 'from': OLD_TREE, 'to': new_tree, 'paths': FILES, 'report': str(OUT / 'bundles-apply.json')})
    json.dump(inv, open(HERE / 'candidate-inventory.json', 'w'), indent=1)
    with open(HERE / 'candidate-changed-paths.tsv', 'w') as f:
        f.write('status\tmode\tsha256\tblob\tdecision\tpath\n')
        for c in changed: f.write(f"{c['status']}\t{c['newMode']}\t{c['sha256'] or '-'}\t{c['newBlob']}\t{c['decision']}\t{c['path']}\n")
    rep.update({'newTree': new_tree, 'reDerivedTree': rtree, 'treeDelta': delta, 'changedVsUpstream': len(changed), 'candidateAllSha256': sha(lst), 'candidateFiles': lst.count(b'\n')})
    json.dump(rep, open(OUT / 'bundles-apply.json', 'w'), indent=1)
    print(json.dumps({k: rep[k] for k in ('newTree', 'reDerivedTree', 'treeDelta', 'changedVsUpstream', 'candidateAllSha256', 'candidateFiles')}, indent=1)); print('BUNDLES-REFRESH-OK')

if __name__ == '__main__':
    main()
